import XCTest
@testable import TCCCReports

/// The official DD Form 1380 (JUN 2014) field values. Field names come from
/// `TCCC_IOS/Resources/DD1380/DD1380_JUN2014_fields.json`, generated by
/// `tools/prepare_dd1380_template.py` with every name verified against the print.
final class DD1380OfficialFormTests: XCTestCase {

    // MARK: - Fixtures

    private struct ManifestField: Decodable {
        let name: String
        let type: String
    }

    private func manifest() throws -> [String: String] {
        var root = URL(fileURLWithPath: #filePath)
        for _ in 0..<5 { root.deleteLastPathComponent() }
        let url = root.appendingPathComponent("TCCC_IOS/Resources/DD1380/DD1380_JUN2014_fields.json")
        let fields = try JSONDecoder().decode([ManifestField].self, from: Data(contentsOf: url))
        return Dictionary(uniqueKeysWithValues: fields.map { ($0.name, $0.type) })
    }

    private func fullCard() -> DD1380CardData {
        var c = DD1380CardData()
        c.battleRosterNumber = "JD4471"
        c.evacCategory = .urgent
        c.nameLastFirst = "DOE, JOHN"
        c.last4 = "4471"
        c.sex = .male
        c.dateDDMMMYY = "14-NOV-23"
        c.timeHHMM = "2213Z"
        c.service = "USA"
        c.unit = "2/75 RGR"
        c.allergies = "PCN"
        c.mechanisms.gsw = true
        c.mechanisms.other = true
        c.mechanisms.otherText = "blast"
        c.tourniquets = [DD1380TourniquetEntry(limb: .rightLeg, timeHHMM: "2213")]
        c.sectionCReadings = (1...4).map {
            DD1380SectionCReading(timeHHMM: "22\($0)0", pulse: "9\($0) radial", bloodPressure: "12\($0)/8\($0)",
                                  respiratoryRate: "1\($0)", spo2: "9\($0)", avpu: "A", pain: "\($0)")
        }
        c.treatments.tqExtremity = true
        c.treatments.tqTypeText = "CAT"
        c.treatments.dressingHemostatic = true
        c.treatments.dressingTypeText = "Combat Gauze"
        c.treatments.airwayNPA = true
        c.treatments.airwayTypeText = "28 Fr"
        c.treatments.breathingChestSeal = true
        c.treatments.breathingTypeText = "vented"
        c.fluids = [DD1380FluidEntry(name: "LR", volume: "500 mL", route: "IV", timeHHMM: "2220")]
        c.bloodProducts = [DD1380FluidEntry(name: "LTOWB", volume: "1 U", route: "IO", timeHHMM: "2225")]
        c.medications = [
            DD1380MedicationEntry(category: .analgesic, name: "Ketamine", dose: "50 mg", route: "IM", timeHHMM: "2215"),
            DD1380MedicationEntry(category: .antibiotic, name: "Moxifloxacin", dose: "400 mg", route: "PO", timeHHMM: "2216"),
            DD1380MedicationEntry(category: .other, name: "TXA", dose: "2 g", route: "IV", timeHHMM: "2217"),
        ]
        c.otherTreatments.combatPillPack = true
        c.otherTreatments.eyeShieldRight = true
        c.otherTreatments.splint = true
        c.otherTreatments.hypothermiaPrevention = true
        c.otherTreatments.hypothermiaType = "HPMK"
        c.notes = "Hemorrhage: right thigh"
        c.firstResponderName = "HAWK, SAM"
        c.firstResponderLast4 = "1234"
        return c
    }

    // MARK: - Template agreement

    func testEveryProducedFieldExistsInTemplate() throws {
        let fields = try manifest()
        let values = DD1380OfficialForm.values(for: fullCard())
        for name in values.text.keys {
            XCTAssertEqual(fields[name], "text", "\(name) is not a text field in the template")
        }
        for name in values.checked {
            XCTAssertEqual(fields[name], "checkbox", "\(name) is not a checkbox in the template")
        }
    }

    func testBlankCardWritesNothing() {
        let values = DD1380OfficialForm.values(for: DD1380CardData())
        XCTAssertTrue(values.text.values.allSatisfy(\.isEmpty), "\(values.text.filter { !$0.value.isEmpty })")
        XCTAssertTrue(values.checked.isEmpty)
        XCTAssertNil(values.continuationNotes)
        XCTAssertNil(values.text["allergies"].flatMap { $0.isEmpty ? nil : $0 }, "blank allergies must never become NKDA")
    }

    // MARK: - §A header

    func testEvacChecksFrontAndBack() {
        var c = DD1380CardData()
        c.evacCategory = .urgent
        XCTAssertEqual(DD1380OfficialForm.values(for: c).checked, ["evac_urgent", "evac_urgent_back"])
        c.evacCategory = .routine
        XCTAssertEqual(DD1380OfficialForm.values(for: c).checked, ["evac_routine", "evac_routine_back"])
    }

    func testBRNumberOnBothPages() {
        let values = DD1380OfficialForm.values(for: fullCard())
        XCTAssertEqual(values.text["br_number"], "JD4471")
        XCTAssertEqual(values.text["br_number_back"], "JD4471")
    }

    func testHeaderFields() {
        let t = DD1380OfficialForm.values(for: fullCard()).text
        XCTAssertEqual(t["name"], "DOE, JOHN")
        XCTAssertEqual(t["last4"], "4471")
        XCTAssertEqual(t["date"], "14-NOV-23")
        XCTAssertEqual(t["time"], "2213Z")
        XCTAssertEqual(t["service"], "USA")
        XCTAssertEqual(t["unit"], "2/75 RGR")
        XCTAssertEqual(t["allergies"], "PCN")
        XCTAssertEqual(t["responder_name"], "HAWK, SAM")
        XCTAssertEqual(t["responder_last4"], "1234")
    }

    func testSexAndMechanism() {
        var c = DD1380CardData()
        c.sex = .female
        c.mechanisms.other = true
        c.mechanisms.otherText = "blast"
        let values = DD1380OfficialForm.values(for: c)
        XCTAssertEqual(values.checked, ["sex_f", "moi_other"])
        XCTAssertEqual(values.text["moi_other_text"], "blast")
    }

    func testEveryMechanismBox() {
        let cases: [(WritableKeyPath<DD1380MechanismFlags, Bool>, String)] = [
            (\.artillery, "moi_artillery"), (\.blunt, "moi_blunt"), (\.burn, "moi_burn"),
            (\.fall, "moi_fall"), (\.grenade, "moi_grenade"), (\.gsw, "moi_gsw"),
            (\.ied, "moi_ied"), (\.landmine, "moi_landmine"), (\.mvc, "moi_mvc"),
            (\.rpg, "moi_rpg"), (\.other, "moi_other"),
        ]
        for (path, field) in cases {
            var c = DD1380CardData()
            c.mechanisms[keyPath: path] = true
            XCTAssertEqual(DD1380OfficialForm.values(for: c).checked, [field])
        }
    }

    // MARK: - §B tourniquets

    func testTourniquetCorners() {
        var c = DD1380CardData()
        c.tourniquets = [
            DD1380TourniquetEntry(limb: .rightLeg, timeHHMM: "2213"),
            DD1380TourniquetEntry(limb: .rightLeg, timeHHMM: "2230"),
            DD1380TourniquetEntry(limb: nil, timeHHMM: "2240", locationText: "junctional groin"),
            DD1380TourniquetEntry(limb: .leftArm, type: "SOFTT-W", timeHHMM: "2245"),
        ]
        let t = DD1380OfficialForm.values(for: c).text
        XCTAssertEqual(t["tq_r_leg_time"], "2213")
        XCTAssertEqual(t["tq_r_leg_type"] ?? "", "", "TQ device is never inferred")
        XCTAssertEqual(t["tq_l_arm_type"], "SOFTT-W")
        XCTAssertEqual(t["tq_l_arm_time"], "2245")
        let notes = t["notes"] ?? ""
        XCTAssertTrue(notes.contains("TQ: R Leg 2230"), notes)
        XCTAssertTrue(notes.contains("TQ: junctional groin 2240"), notes)
    }

    // MARK: - §C vitals

    func testVitalsColumnsAndPain() {
        let t = DD1380OfficialForm.values(for: fullCard()).text
        for n in 1...4 {
            XCTAssertEqual(t["vitals\(n)_time"], "22\(n)0")
            XCTAssertEqual(t["vitals\(n)_pulse"], "9\(n) radial")
            XCTAssertEqual(t["vitals\(n)_sbp"], "12\(n)")
            XCTAssertEqual(t["vitals\(n)_dbp"], "8\(n)")
            XCTAssertEqual(t["vitals\(n)_rr"], "1\(n)")
            XCTAssertEqual(t["vitals\(n)_spo2"], "9\(n)")
            XCTAssertEqual(t["vitals\(n)_avpu"], "A")
            XCTAssertEqual(t["vitals\(n)_pain"], "\(n)")
        }
    }

    func testBloodPressureSplits() {
        var c = DD1380CardData()
        c.sectionCReadings = [
            DD1380SectionCReading(timeHHMM: "2213", bloodPressure: "120/80"),
            DD1380SectionCReading(timeHHMM: "2220", bloodPressure: "palpable"),
            DD1380SectionCReading(timeHHMM: "2225", bloodPressure: " 90 / 60 "),
        ]
        let t = DD1380OfficialForm.values(for: c).text
        XCTAssertEqual(t["vitals1_sbp"], "120")
        XCTAssertEqual(t["vitals1_dbp"], "80")
        XCTAssertEqual(t["vitals2_sbp"], "palpable")
        XCTAssertEqual(t["vitals2_dbp"] ?? "", "")
        XCTAssertEqual(t["vitals3_sbp"], "90")
        XCTAssertEqual(t["vitals3_dbp"], "60")
    }

    func testMoreThanFourReadingsGoToNotes() {
        var c = DD1380CardData()
        c.sectionCReadings = (1...5).map { DD1380SectionCReading(timeHHMM: "230\($0)", pulse: "10\($0)") }
        let t = DD1380OfficialForm.values(for: c).text
        XCTAssertEqual(t["vitals4_time"], "2304")
        XCTAssertTrue((t["notes"] ?? "").contains("Vitals 2305: P 105"), t["notes"] ?? "")
    }

    // MARK: - §E / §F treatments, fluids, meds

    func testTreatmentBoxes() {
        let flagCases: [(WritableKeyPath<DD1380TreatmentFlags, Bool>, String)] = [
            (\.tqExtremity, "tq_extremity"), (\.tqJunctional, "tq_junctional"), (\.tqTruncal, "tq_truncal"),
            (\.dressingHemostatic, "dressing_hemostatic"), (\.dressingPressure, "dressing_pressure"),
            (\.dressingOther, "dressing_other"),
            (\.airwayIntact, "airway_intact"), (\.airwayNPA, "airway_npa"), (\.airwayCRIC, "airway_cric"),
            (\.airwayETTube, "airway_et_tube"), (\.airwaySGA, "airway_sga"),
            (\.breathingO2, "breathing_o2"), (\.breathingNeedleD, "breathing_needle_d"),
            (\.breathingChestTube, "breathing_chest_tube"), (\.breathingChestSeal, "breathing_chest_seal"),
        ]
        for (path, field) in flagCases {
            var c = DD1380CardData()
            c.treatments[keyPath: path] = true
            XCTAssertEqual(DD1380OfficialForm.values(for: c).checked, [field])
        }
        let t = DD1380OfficialForm.values(for: fullCard()).text
        XCTAssertEqual(t["tq_type_text"], "CAT")
        XCTAssertEqual(t["dressing_type_text"], "Combat Gauze")
        XCTAssertEqual(t["airway_type_text"], "28 Fr")
        XCTAssertEqual(t["breathing_type_text"], "vented")
    }

    func testOtherRow() {
        let otherCases: [(WritableKeyPath<DD1380OtherTreatmentFlags, Bool>, Set<String>)] = [
            (\.combatPillPack, ["other_pill_pack"]),
            (\.eyeShieldRight, ["other_eye_shield", "other_eye_shield_r"]),
            (\.eyeShieldLeft, ["other_eye_shield", "other_eye_shield_l"]),
            (\.splint, ["other_splint"]),
            (\.hypothermiaPrevention, ["other_hypothermia"]),
        ]
        for (path, fields) in otherCases {
            var c = DD1380CardData()
            c.otherTreatments[keyPath: path] = true
            XCTAssertEqual(DD1380OfficialForm.values(for: c).checked, fields)
        }
        XCTAssertEqual(DD1380OfficialForm.values(for: fullCard()).text["other_hypothermia_type"], "HPMK")
    }

    func testFluidsBloodAndMedsRows() {
        let t = DD1380OfficialForm.values(for: fullCard()).text
        XCTAssertEqual(t["fluid1_name"], "LR")
        XCTAssertEqual(t["fluid1_volume"], "500 mL")
        XCTAssertEqual(t["fluid1_route"], "IV")
        XCTAssertEqual(t["fluid1_time"], "2220")
        XCTAssertEqual(t["blood1_name"], "LTOWB")
        XCTAssertEqual(t["blood1_route"], "IO", "routes outside the official drop-down list are kept")
        XCTAssertEqual(t["analgesic1_name"], "Ketamine")
        XCTAssertEqual(t["analgesic1_dose"], "50 mg")
        XCTAssertEqual(t["analgesic1_route"], "IM")
        XCTAssertEqual(t["analgesic1_time"], "2215")
        XCTAssertEqual(t["antibiotic1_name"], "Moxifloxacin")
        XCTAssertEqual(t["othermed1_name"], "TXA")
        XCTAssertEqual(t["othermed1_time"], "2217")
    }

    func testMedicationOverflowGoesToNotes() {
        var c = DD1380CardData()
        c.medications = (1...4).map { DD1380MedicationEntry(category: .analgesic, name: "Analgesic\($0)", timeHHMM: "230\($0)") }
            + (1...3).map { DD1380MedicationEntry(category: .antibiotic, name: "Antibiotic\($0)", timeHHMM: "231\($0)") }
            + (1...3).map { DD1380MedicationEntry(category: .other, name: "Other\($0)", timeHHMM: "232\($0)") }
        c.fluids = (1...3).map { DD1380FluidEntry(name: "Fluid\($0)", volume: "\($0)00 mL") }
        c.bloodProducts = (1...3).map { DD1380FluidEntry(name: "Blood\($0)") }
        let t = DD1380OfficialForm.values(for: c).text
        XCTAssertEqual(t["analgesic3_name"], "Analgesic3")
        XCTAssertEqual(t["antibiotic2_name"], "Antibiotic2")
        XCTAssertEqual(t["othermed2_name"], "Other2")
        XCTAssertEqual(t["fluid2_name"], "Fluid2")
        XCTAssertEqual(t["blood2_name"], "Blood2")
        let notes = t["notes"] ?? ""
        for expected in ["Analgesic: Analgesic4 2304", "Antibiotic: Antibiotic3 2313",
                         "Medication: Other3 2323", "Fluid: Fluid3 300 mL", "Blood product: Blood3"] {
            XCTAssertTrue(notes.contains(expected), "missing \(expected) in \(notes)")
        }
    }

    func testCardNotesComeFirst() {
        var c = DD1380CardData()
        c.notes = "Hemorrhage: right thigh"
        c.medications = (1...4).map { DD1380MedicationEntry(category: .analgesic, name: "A\($0)") }
        let notes = DD1380OfficialForm.values(for: c).text["notes"] ?? ""
        XCTAssertTrue(notes.hasPrefix("Hemorrhage: right thigh\n"), notes)
    }

    // MARK: - §G notes capacity

    func testNotesSplitAtLineBoundary() {
        let lines = (1...30).map { String(format: "line %02d of the notes.", $0) }
        let split = DD1380OfficialForm.splitNotes(lines.joined(separator: "\n"), charsPerLine: 95, maxLines: 11)
        XCTAssertEqual(split.onForm.components(separatedBy: "\n").count, 11)
        XCTAssertTrue(split.onForm.hasSuffix("line 10 of the notes.\n(continued on next page)"), split.onForm)
        XCTAssertEqual(split.overflow?.components(separatedBy: "\n").first, "line 11 of the notes.")
        XCTAssertEqual(split.overflow?.components(separatedBy: "\n").count, 20)
    }

    func testNotesThatFitAreNotSplit() {
        let split = DD1380OfficialForm.splitNotes("short note\nsecond line", charsPerLine: 95, maxLines: 11)
        XCTAssertEqual(split.onForm, "short note\nsecond line")
        XCTAssertNil(split.overflow)
    }

    func testOneLongLineSplitsAtAWord() {
        let text = Array(repeating: "word", count: 400).joined(separator: " ")   // 1,999 characters
        let split = DD1380OfficialForm.splitNotes(text, charsPerLine: 95, maxLines: 11)
        XCTAssertTrue(split.onForm.hasSuffix("\n(continued on next page)"))
        let kept = split.onForm.replacingOccurrences(of: "\n(continued on next page)", with: "")
        XCTAssertLessThanOrEqual(kept.count, 95 * 10)
        XCTAssertTrue(kept.hasSuffix("word"))
        XCTAssertEqual((kept + " " + (split.overflow ?? "")).count, text.count, "nothing is lost")
    }

    func testLongNotesProduceContinuation() {
        var c = DD1380CardData()
        c.notes = (1...40).map { "Note line \($0)" }.joined(separator: "\n")
        let values = DD1380OfficialForm.values(for: c)
        XCTAssertTrue(values.text["notes"]?.hasSuffix("(continued on next page)") == true)
        XCTAssertTrue(values.continuationNotes?.hasSuffix("Note line 40") == true)
    }
}
